//! `Pointy Arrow` (`EBG_Spell_014`) — Tier 1 token spell (`1` Gold), generated by `Weapons Forge`.
//!
//! Give a minion +4 Attack. Spell power adds both of its stats (`+4/+1` with an extra `+1`
//! Health).

use super::targeted_minion;
use crate::cards::CardHooks;
use crate::model::Unit;
use crate::rng::Rng;
use crate::tavern::{CardPool, MinionSlot, TavernState};

/// Hooks registered for this spell in [`super::behaviors`].
pub fn hooks() -> CardHooks {
    targeted_minion(cast)
}

/// `Pointy Arrow`: give a minion +4 Attack.
pub fn cast(state: &mut TavernState, _: &Unit, target: MinionSlot, _: &mut CardPool, _: &mut Rng) {
    let (atk, hp) = state.auras.spell_stat_buff(4, 0);
    if let Some(target) = state.minion_mut(target) {
        target.add_stats(atk, hp);
    }
}
